//
//  BellScheduleTests.swift
//
//  Bell-timing tests that run on Linux (`swift test` in ios/) and macOS.
//  They check the core against the shared fixtures in docs/fixtures, which
//  are generated by an independent reference (scripts/bell_fixtures.py).
//

import XCTest
#if canImport(ImpermanenceCore)
@testable import ImpermanenceCore
#else
@testable import Impermanence
#endif

// MARK: - Fixture loading

private struct PortableBell: Decodable { let soundId: Int; let numRings: Int }
private struct PortableSegment: Decodable {
    let id: String; let name: String; let durationSeconds: Int; let customEndBell: PortableBell?
}
private struct PortableDay: Decodable {
    let id: String; let name: String; let startTimeSeconds: Int; let segments: [PortableSegment]
    let startBell: PortableBell; let manualBell: PortableBell; let defaultBell: PortableBell; let theme: String

    var day: Day {
        Day(id: UUID(uuidString: id) ?? UUID(), name: name, startTime: TimeInterval(startTimeSeconds),
            segments: segments.map {
                Day.Segment(id: UUID(uuidString: $0.id) ?? UUID(), name: $0.name,
                            duration: TimeInterval($0.durationSeconds),
                            customEndBell: $0.customEndBell.map { Bell(soundId: $0.soundId, numRings: $0.numRings) })
            },
            startBell: Bell(soundId: startBell.soundId, numRings: startBell.numRings),
            manualBell: Bell(soundId: manualBell.soundId, numRings: manualBell.numRings),
            defaultBell: Bell(soundId: defaultBell.soundId, numRings: defaultBell.numRings),
            theme: Theme(rawValue: theme) ?? .teal)
    }
}
private struct ExpectedEvent: Decodable, Equatable {
    let instant: String; let kind: String; let segmentIndex: Int; let numRings: Int; let soundId: Int
}
private struct BellFixture: Decodable {
    let name: String; let zone: String; let loopDays: Bool
    let sessionStart: String; let until: String
    let day: PortableDay; let expectedEvents: [ExpectedEvent]
}

private let iso: ISO8601DateFormatter = {
    let f = ISO8601DateFormatter()
    f.formatOptions = [.withInternetDateTime]
    return f
}()

private func calendar(_ zone: String) -> Calendar {
    var c = Calendar(identifier: .gregorian)
    c.timeZone = TimeZone(identifier: zone)!
    return c
}

private func fixturesDirectory() -> URL {
    // ios/CoreTests/BellScheduleTests.swift -> repo root
    URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("docs/fixtures")
}

private func loadFixtures() throws -> [BellFixture] {
    let dir = fixturesDirectory()
    let files = try FileManager.default.contentsOfDirectory(atPath: dir.path)
        .filter { $0.hasPrefix("bell-") && $0.hasSuffix(".json") }
        .sorted()
    return try files.map { try JSONDecoder().decode(BellFixture.self, from: Data(contentsOf: dir.appendingPathComponent($0))) }
}

private func session(for fixture: BellFixture, day: Day, cal: Calendar) -> TimingSession {
    let start = iso.date(from: fixture.sessionStart)!
    let anchor = DaySchedule.initialOccurrence(of: day, at: start, calendar: cal).date
    return .day(.init(dayID: day.id, openedAt: start, anchor: anchor, loopDays: fixture.loopDays))
}

final class BellScheduleTests: XCTestCase {

    // MARK: Shared fixtures

    func testFixturesExist() throws {
        XCTAssertGreaterThanOrEqual(try loadFixtures().count, 15)
    }

    func testSessionEventsMatchSharedFixtures() throws {
        for fixture in try loadFixtures() {
            let cal = calendar(fixture.zone)
            let day = fixture.day.day
            let start = iso.date(from: fixture.sessionStart)!
            let until = iso.date(from: fixture.until)!
            let events = session(for: fixture, day: day, cal: cal).events(day: day, window: start...until, calendar: cal)
            let actual = events.map {
                ExpectedEvent(instant: iso.string(from: $0.instant), kind: $0.kind.rawValue,
                              segmentIndex: $0.segmentIndex, numRings: $0.bell.numRings, soundId: $0.bell.soundId)
            }
            XCTAssertEqual(actual, fixture.expectedEvents, "fixture \(fixture.name)")
        }
    }

    /// Runs the planner tick by tick across each fixture, the way the engine
    /// does, with irregular ticks. Every chime must play exactly once, on its
    /// exact instant.
    func testPlannerPlaysEveryFixtureChimeOnceOnTime() throws {
        var rng = SeededGenerator(seed: 42)
        for fixture in try loadFixtures() {
            let cal = calendar(fixture.zone)
            let day = fixture.day.day
            let start = iso.date(from: fixture.sessionStart)!
            let until = iso.date(from: fixture.until)!
            let s = session(for: fixture, day: day, cal: cal)
            let expected = DaySchedule.chimes(for: s.events(day: day, window: start...until.addingTimeInterval(60), calendar: cal))
                .filter { $0.instant <= until.addingTimeInterval(40) }

            // Ticks: every 20 s, plus ticks in the second before each chime.
            var ticks = stride(from: start.timeIntervalSince1970, through: until.timeIntervalSince1970, by: 20).map { $0 }
            for chime in expected {
                ticks.append(chime.instant.timeIntervalSince1970 - Double.random(in: 0.05...0.95, using: &rng))
            }
            ticks.sort()

            var handled: Set<String> = []
            var played: [ChimePlanner.Playback] = []
            for t in ticks {
                let now = Date(timeIntervalSince1970: t)
                let window = now.addingTimeInterval(-ChimePlanner.catchUpLimit - 60)...now.addingTimeInterval(3600)
                let chimes = DaySchedule.chimes(for: s.events(day: day, window: window, calendar: cal))
                let d = ChimePlanner.decide(chimes: chimes, handled: handled, sessionStart: start, now: now)
                handled.formUnion(d.handled)
                played += d.play
            }
            let playedIDs = played.map(\.chime.id)
            XCTAssertEqual(Set(playedIDs).count, playedIDs.count, "\(fixture.name): a chime played twice")
            XCTAssertEqual(Set(playedIDs), Set(expected.map(\.id)), "\(fixture.name): played set differs")
            for p in played {
                XCTAssertEqual(p.playAt.timeIntervalSince1970, p.chime.instant.timeIntervalSince1970, accuracy: 0.001,
                               "\(fixture.name): \(p.chime.id) not on time")
            }
        }
    }

    // MARK: DST and time zones

    func testStartTimeIsWallClockOnDSTDays() {
        let la = calendar("America/Los_Angeles")
        for date in [CalendarDay(year: 2026, month: 3, day: 8), CalendarDay(year: 2026, month: 11, day: 1),
                     CalendarDay(year: 2026, month: 6, day: 1)] {
            let instant = DaySchedule.instant(ofSecondsAfterMidnight: 7 * 3600, on: date, calendar: la)
            let c = la.dateComponents([.year, .month, .day, .hour, .minute, .second], from: instant)
            XCTAssertEqual([c.year, c.month, c.day, c.hour, c.minute, c.second], [date.year, date.month, date.day, 7, 0, 0])
        }
    }

    /// Every zone, a week around each of its transitions in 2026-2027:
    /// a valid wall-clock start lands on that wall-clock time, a start in a
    /// gap moves forward by the gap, and segments last exactly their duration.
    func testWallClockStartAcrossAllZoneTransitions() {
        var rng = SeededGenerator(seed: 7)
        let from = Date(timeIntervalSince1970: 1_767_225_600) // 2026-01-01
        let to = Date(timeIntervalSince1970: 1_830_297_600)   // 2028-01-01
        var checked = 0
        for zoneID in TimeZone.knownTimeZoneIdentifiers {
            guard let tz = TimeZone(identifier: zoneID) else { continue }
            var cal = Calendar(identifier: .gregorian)
            cal.timeZone = tz
            var t = from
            while let next = tz.nextDaylightSavingTimeTransition(after: t), next < to {
                t = next
                for dayOffset in -1...1 {
                    let date = CalendarDay(containing: next.addingTimeInterval(TimeInterval(dayOffset) * 86_400), calendar: cal)
                    for _ in 0..<12 {
                        let seconds = Int.random(in: 0..<86_400, using: &rng) / 60 * 60
                        let day = Day(name: "z", startTime: TimeInterval(seconds),
                                      segments: [Day.Segment(name: "a", duration: 2700), Day.Segment(name: "b", duration: 1800)])
                        let occ = DaySchedule.occurrence(of: day, on: date, calendar: cal)
                        let c = cal.dateComponents([.year, .month, .day, .hour, .minute, .second], from: occ.start)
                        let wall = (c.hour! * 3600 + c.minute! * 60 + c.second!)
                        let sameDate = CalendarDay(year: c.year!, month: c.month!, day: c.day!) == date
                        if sameDate && wall == seconds {
                            // exact
                        } else {
                            // Must be a gap: the requested time doesn't exist,
                            // and the result is later by the gap length.
                            let before = tz.secondsFromGMT(for: occ.start.addingTimeInterval(-86_400 / 2))
                            let after = tz.secondsFromGMT(for: occ.start)
                            XCTAssertGreaterThan(after, before, "\(zoneID) \(date.key) \(seconds)s: not a gap")
                            let shiftedWall = ((wall - seconds) % 86_400 + 86_400) % 86_400
                            XCTAssertEqual(shiftedWall, after - before, "\(zoneID) \(date.key) \(seconds)s")
                        }
                        XCTAssertEqual(occ.segments[0].end.timeIntervalSince(occ.segments[0].start), 2700)
                        XCTAssertEqual(occ.segments[1].start, occ.segments[0].end)
                        XCTAssertEqual(occ.end.timeIntervalSince(occ.start), 4500)
                        checked += 1
                    }
                }
            }
        }
        XCTAssertGreaterThan(checked, 1000)
    }

    func testRepeatedTimeUsesFirstOccurrence() {
        let la = calendar("America/Los_Angeles")
        let instant = DaySchedule.instant(ofSecondsAfterMidnight: 5400, on: CalendarDay(year: 2026, month: 11, day: 1), calendar: la)
        XCTAssertEqual(iso.string(from: instant), "2026-11-01T08:30:00Z") // 01:30 PDT
    }

    func testTimeZoneChangeKeepsEventIDs() {
        let day = Day.openingDay
        let date = CalendarDay(year: 2026, month: 6, day: 10)
        let ny = DaySchedule.events(for: DaySchedule.occurrence(of: day, on: date, calendar: calendar("America/New_York")), of: day)
        let tokyo = DaySchedule.events(for: DaySchedule.occurrence(of: day, on: date, calendar: calendar("Asia/Tokyo")), of: day)
        XCTAssertEqual(ny.map(\.id), tokyo.map(\.id))
        XCTAssertNotEqual(ny.map(\.instant), tokyo.map(\.instant))
        // Same local wall-clock time in each zone.
        XCTAssertEqual(calendar("Asia/Tokyo").component(.hour, from: tokyo[0].instant), 18)
        XCTAssertEqual(calendar("America/New_York").component(.hour, from: ny[0].instant), 18)
    }

    // MARK: Occurrence selection

    func testInitialOccurrencePicksYesterdayWhileItIsStillRunning() {
        let ny = calendar("America/New_York")
        let night = Day(name: "n", startTime: 22 * 3600, segments: [Day.Segment(name: "a", duration: 3 * 3600)])
        let at0030 = iso.date(from: "2026-06-11T04:30:00Z")! // 00:30 EDT
        XCTAssertEqual(DaySchedule.initialOccurrence(of: night, at: at0030, calendar: ny).date, CalendarDay(year: 2026, month: 6, day: 10))
        let at0130 = iso.date(from: "2026-06-11T05:30:00Z")! // 01:30 EDT, yesterday's has ended
        XCTAssertEqual(DaySchedule.initialOccurrence(of: night, at: at0130, calendar: ny).date, CalendarDay(year: 2026, month: 6, day: 11))
    }

    func testLoopingDoesNotResetARunningDayAtMidnight() {
        let ny = calendar("America/New_York")
        let night = Day(name: "n", startTime: 22 * 3600, segments: [Day.Segment(name: "a", duration: 3 * 3600)])
        let anchor = CalendarDay(year: 2026, month: 6, day: 10)
        let at0030 = iso.date(from: "2026-06-11T04:30:00Z")!
        let occ = DaySchedule.currentOccurrence(of: night, anchor: anchor, at: at0030, loopDays: true, calendar: ny)
        XCTAssertEqual(occ.date, anchor)
        XCTAssertEqual(DayProgress.at(at0030, occurrence: occ).status, .running(segmentIndex: 0))
        let at0130 = iso.date(from: "2026-06-11T05:30:00Z")!
        let later = DaySchedule.currentOccurrence(of: night, anchor: anchor, at: at0130, loopDays: true, calendar: ny)
        XCTAssertEqual(later.date, CalendarDay(year: 2026, month: 6, day: 11))
        XCTAssertEqual(DayProgress.at(at0130, occurrence: later).status, .queued)
    }

    func testNonLoopingStaysCompleteForever() {
        let ny = calendar("America/New_York")
        let anchor = CalendarDay(year: 2026, month: 6, day: 10)
        let muchLater = iso.date(from: "2026-07-10T16:00:00Z")!
        let occ = DaySchedule.currentOccurrence(of: .openingDay, anchor: anchor, at: muchLater, loopDays: false, calendar: ny)
        XCTAssertEqual(occ.date, anchor)
        XCTAssertEqual(DayProgress.at(muchLater, occurrence: occ).status, .complete)
    }

    func testLoopingShowsCompleteUntilMidnightThenQueued() {
        let ny = calendar("America/New_York")
        let anchor = CalendarDay(year: 2026, month: 6, day: 10)
        let at2330 = iso.date(from: "2026-06-11T03:30:00Z")! // 23:30 EDT, Opening Day ended 22:00
        let occ = DaySchedule.currentOccurrence(of: .openingDay, anchor: anchor, at: at2330, loopDays: true, calendar: ny)
        XCTAssertEqual(DayProgress.at(at2330, occurrence: occ).status, .complete)
        let at0010 = iso.date(from: "2026-06-11T04:10:00Z")!
        let next = DaySchedule.currentOccurrence(of: .openingDay, anchor: anchor, at: at0010, loopDays: true, calendar: ny)
        XCTAssertEqual(next.date, CalendarDay(year: 2026, month: 6, day: 11))
        XCTAssertEqual(DayProgress.at(at0010, occurrence: next).status, .queued)
    }

    func testProgressValues() {
        let ny = calendar("America/New_York")
        let occ = DaySchedule.occurrence(of: .openingDay, on: CalendarDay(year: 2026, month: 6, day: 10), calendar: ny)
        let at1810 = occ.start.addingTimeInterval(600)
        let p = DayProgress.at(at1810, occurrence: occ)
        XCTAssertEqual(p.status, .running(segmentIndex: 0))
        XCTAssertEqual(p.elapsed, 600)
        XCTAssertEqual(p.remaining, 2100)
        XCTAssertEqual(p.nextBell, occ.segments[0].end)
        XCTAssertEqual(DayProgress.at(occ.start.addingTimeInterval(-1), occurrence: occ).segmentIndex, -1)
        XCTAssertEqual(DayProgress.at(occ.end, occurrence: occ).segmentIndex, 5)
        XCTAssertEqual(DayProgress.at(occ.end, occurrence: occ).nextBell, nil)
        XCTAssertEqual(DayProgress.at(occ.start, occurrence: nil).status, .empty)
    }

    // MARK: Planner rules

    private func quickSit(start: Date, minutes: Int = 10, startChimes: Int = 1, endChimes: Int = 3) -> TimingSession {
        .quickSit(.init(startedAt: start, durationSeconds: minutes * 60, soundId: 0, startChimes: startChimes, endChimes: endChimes))
    }

    private func chimes(_ s: TimingSession, around now: Date) -> [Chime] {
        DaySchedule.chimes(for: s.events(day: nil, window: now.addingTimeInterval(-3600)...now.addingTimeInterval(3600), calendar: calendar("UTC")))
    }

    func testQuickSitStartChimesRingImmediately() {
        let t0 = iso.date(from: "2026-06-10T12:00:00Z")!
        let s = quickSit(start: t0, startChimes: 2)
        let d = ChimePlanner.decide(chimes: chimes(s, around: t0), handled: [], sessionStart: t0, now: t0)
        XCTAssertEqual(d.play.map(\.chime.id), ["quicksit.start.0"])
        XCTAssertEqual(d.play.first?.playAt, t0)
        let d2 = ChimePlanner.decide(chimes: chimes(s, around: t0), handled: d.handled, sessionStart: t0, now: t0.addingTimeInterval(2.2))
        XCTAssertEqual(d2.play.map(\.chime.id), ["quicksit.start.1"])
        XCTAssertEqual(d2.play.first?.playAt, t0.addingTimeInterval(3))
    }

    func testCatchUpRingsMostRecentEventOnlyWithinLimit() {
        let t0 = iso.date(from: "2026-06-10T12:00:00Z")!
        let day = Day(name: "x", startTime: 12 * 3600, segments: [
            Day.Segment(name: "a", duration: 60), Day.Segment(name: "b", duration: 60), Day.Segment(name: "c", duration: 600),
        ], defaultBell: Bell(soundId: 0, numRings: 2))
        let cal = calendar("UTC")
        let s = TimingSession.day(.init(dayID: day.id, openedAt: t0.addingTimeInterval(-10), anchor: CalendarDay(year: 2026, month: 6, day: 10), loopDays: false))
        let all = DaySchedule.chimes(for: s.events(day: day, window: t0.addingTimeInterval(-600)...t0.addingTimeInterval(3600), calendar: cal))

        // Suspended from before the start until 30 s after the second end bell
        // (12:02:00): start and first end are missed for good; the second end
        // bell rings now, its 2 chimes 3 s apart.
        let now = t0.addingTimeInterval(150)
        let d = ChimePlanner.decide(chimes: all, handled: [], sessionStart: t0.addingTimeInterval(-10), now: now)
        XCTAssertEqual(d.play.map(\.chime.id), ["2026-06-10.end.1.0", "2026-06-10.end.1.1"])
        XCTAssertEqual(d.play.map(\.playAt), [now, now.addingTimeInterval(3)])
        XCTAssertTrue(d.handled.isSuperset(of: ["2026-06-10.start.0", "2026-06-10.end.0.0", "2026-06-10.end.0.1"]))

        // More than 60 s late: nothing rings, everything past is skipped.
        let late = t0.addingTimeInterval(200)
        let d2 = ChimePlanner.decide(chimes: all, handled: [], sessionStart: t0.addingTimeInterval(-10), now: late)
        XCTAssertTrue(d2.play.isEmpty)
        XCTAssertTrue(d2.handled.contains("2026-06-10.end.1.1"))

        // Handled chimes never ring again.
        let d3 = ChimePlanner.decide(chimes: all, handled: d.handled, sessionStart: t0.addingTimeInterval(-10), now: now.addingTimeInterval(1))
        XCTAssertTrue(d3.play.isEmpty)
    }

    func testNothingBeforeSessionStartEverRings() {
        let t0 = iso.date(from: "2026-06-10T12:00:00Z")!
        let s = quickSit(start: t0)
        let all = chimes(s, around: t0)
        let d = ChimePlanner.decide(chimes: all, handled: [], sessionStart: t0.addingTimeInterval(1), now: t0.addingTimeInterval(5))
        XCTAssertTrue(d.play.isEmpty)
    }

    func testNotificationSafetyNetCoversFutureUnhandledChimes() {
        let t0 = iso.date(from: "2026-06-10T12:00:00Z")!
        let s = quickSit(start: t0, minutes: 20, endChimes: 3)
        let all = chimes(s, around: t0)
        let net = ChimePlanner.notificationChimes(chimes: all, handled: ["quicksit.start.0"], sessionStart: t0, now: t0.addingTimeInterval(1))
        XCTAssertEqual(net.map(\.id), ["quicksit.end.0", "quicksit.end.1", "quicksit.end.2"])
        XCTAssertEqual(net.first?.instant, t0.addingTimeInterval(1200))
        let fullDay = Day.fullDay
        let cal = calendar("UTC")
        let ds = TimingSession.day(.init(dayID: fullDay.id, openedAt: t0, anchor: CalendarDay(year: 2026, month: 6, day: 11), loopDays: true))
        let many = DaySchedule.chimes(for: ds.events(day: Day(name: "x", startTime: 0, segments: fullDay.segments, startBell: Bell(soundId: 0, numRings: 3), defaultBell: Bell(soundId: 0, numRings: 3)),
                                                     window: t0...t0.addingTimeInterval(3 * 86_400), calendar: cal))
        let capped = ChimePlanner.notificationChimes(chimes: many, handled: [], sessionStart: t0, now: iso.date(from: "2026-06-11T00:00:00Z")!)
        XCTAssertEqual(capped.count, ChimePlanner.maxPendingNotifications)
        XCTAssertEqual(capped, capped.sorted { $0.instant < $1.instant })
    }

    func testFinished() {
        let t0 = iso.date(from: "2026-06-10T12:00:00Z")!
        let s = quickSit(start: t0, minutes: 1, endChimes: 3)
        let cal = calendar("UTC")
        XCTAssertFalse(s.isFinished(at: t0.addingTimeInterval(65), day: nil, calendar: cal))
        XCTAssertTrue(s.isFinished(at: t0.addingTimeInterval(67), day: nil, calendar: cal))
        let loop = TimingSession.day(.init(dayID: UUID(), openedAt: t0, anchor: CalendarDay(year: 2026, month: 6, day: 10), loopDays: true))
        XCTAssertFalse(loop.isFinished(at: t0.addingTimeInterval(1e7), day: .openingDay, calendar: cal))
        XCTAssertTrue(loop.isFinished(at: t0, day: nil, calendar: cal))
    }

    func testSessionRoundTripsThroughJSON() throws {
        let s = TimingSession.day(.init(dayID: UUID(), openedAt: Date(timeIntervalSince1970: 1_781_000_000),
                                        anchor: CalendarDay(year: 2026, month: 6, day: 10), loopDays: true))
        let data = try JSONEncoder().encode(s)
        XCTAssertEqual(try JSONDecoder().decode(TimingSession.self, from: data), s)
    }

    func testDayStartTimeSetterKeepsWallClock() {
        var day = Day(name: "x", startTime: 0, segments: [])
        var c = DateComponents()
        c.year = 2026; c.month = 3; c.day = 8; c.hour = 7; c.minute = 15
        day.startTimeAsDate = Calendar.current.date(from: c)!
        XCTAssertEqual(day.startTime, 7 * 3600 + 15 * 60)
    }
}

/// Deterministic random numbers so failures are reproducible.
struct SeededGenerator: RandomNumberGenerator {
    private var state: UInt64
    init(seed: UInt64) { state = seed &+ 0x9E37_79B9_7F4A_7C15 }
    mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return z ^ (z >> 31)
    }
}
